def comps(grid, val):
    R,C=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c]!=val or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          x,y=q.pop(); cells.append((x,y))
